248	function parseMultipart(bodyBuf, boundary) {
249	  const boundaryBuf = Buffer.from(`--${boundary}`)
250	  const crlfcrlf = Buffer.from('\r\n\r\n')
251	  const parts = []
252	  let idx = bodyBuf.indexOf(boundaryBuf)
253	  while (idx !== -1) {
254	    const nextIdx = bodyBuf.indexOf(boundaryBuf, idx + boundaryBuf.length)
255	    if (nextIdx === -1) break
256	    let partStart = idx + boundaryBuf.length
257	    if (bodyBuf[partStart] === 0x0d && bodyBuf[partStart + 1] === 0x0a) partStart += 2
258	    let partEnd = nextIdx
259	    if (bodyBuf[partEnd - 2] === 0x0d && bodyBuf[partEnd - 1] === 0x0a) partEnd -= 2
260	    if (partEnd > partStart) parts.push(bodyBuf.subarray(partStart, partEnd))
261	    idx = nextIdx
262	  }
263	  const result = { fields: {}, files: {} }
264	  for (const part of parts) {
265	    const headerEnd = part.indexOf(crlfcrlf)
266	    if (headerEnd === -1) continue
267	    const headerStr = part.subarray(0, headerEnd).toString('utf8')
268	    const data = part.subarray(headerEnd + 4)
269	    const nameMatch = /name="([^"]*)"/.exec(headerStr)
270	    const filenameMatch = /filename="([^"]*)"/.exec(headerStr)
271	    const ctMatch = /Content-Type:\s*([^\r\n]+)/i.exec(headerStr)
272	    const name = nameMatch ? nameMatch[1] : ''
273	    if (!name) continue
274	    if (filenameMatch) {
275	      result.files[name] = {
276	        filename: filenameMatch[1],
277	        contentType: ctMatch ? ctMatch[1].trim() : 'application/octet-stream',
278	        data,
279	      }
280	    } else {
281	      result.fields[name] = data.toString('utf8')
282	    }
283	  }
284	  return result
285	}
