757	function ensureRealDomainCert(outDir) {
758	  const key = path.join(outDir, 'social-realmodel-key.pem')
759	  const cert = path.join(outDir, 'social-realmodel-cert.pem')
760	  if (fs.existsSync(key) && fs.existsSync(cert)) return { key, cert }
761	  fs.mkdirSync(outDir, { recursive: true })
762	  const r = spawnSync('openssl', [
763	    'req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '30',
764	    '-keyout', key, '-out', cert, '-subj', '/CN=social-realmodel-fixture',
765	  ], { encoding: 'utf8' })
766	  if (r.status !== 0 || !fs.existsSync(cert)) return null
767	  return { key, cert }
768	}
