824	  const bodyBuf = await readBodyBuffer(req)
825	  const parsed = parseMultipart(bodyBuf, boundary)
826	  const file = parsed.files['file']
827	  const caption = (parsed.fields['caption'] || '').trim()
828	  if (!file || !caption) return sendJson(res, 400, { error: '파일 또는 문구 누락' })
829	  const sha256 = crypto.createHash('sha256').update(file.data).digest('hex')
830	  const id = String(state.publishes.length + 1)
831	  state.publishes.push({ id, bytes: file.data.length, sha256, caption, at: Date.now(), viaHost: req.headers.host || '' })
832	  return sendJson(res, 200, { id })
833	}
