835	export const REAL_DOMAIN_HOST = 'www.instagram.com'
836	
837	/**
838	 * `state`(startSocialFixtures 가 반환한 것과 **같은 객체**)를 공유하는 HTTPS 서버를 띄운다 —
839	 * `/state` 가 여기서 받은 게시도 그대로 반영한다(관측 지점을 하나로 유지).
840	 * @returns {Promise<{port:number, hostResolverRule:string, close:() => Promise<void>} | null>} 실패 시 null.
841	 */
842	export async function startInstagramHttpsFixture(state, outDir) {
843	  const certPaths = ensureRealDomainCert(outDir)
844	  if (!certPaths) return null
845	
846	  const server = https.createServer(
847	    { key: fs.readFileSync(certPaths.key), cert: fs.readFileSync(certPaths.cert) },
848	    (req, res) => {
849	      let urlObj
850	      try { urlObj = new URL(req.url, `https://${req.headers.host || REAL_DOMAIN_HOST}`) } catch { urlObj = null }
851	      const pathname = urlObj ? urlObj.pathname : req.url
852	      Promise.resolve().then(async () => {
853	        if (req.method === 'GET' && (pathname === '/' || pathname === '')) {
854	          return sendHtml(res, 200, instagramWizardHtml())
855	        }
856	        if (req.method === 'POST' && pathname === '/sns/publish') {
857	          return handlePublishOnState(state, req, res)
858	        }
859	        const postMatch = /^\/sns\/post\/(\w+)$/.exec(pathname)
860	        if (req.method === 'GET' && postMatch) {
861	          const rec = state.publishes.find((p) => p.id === postMatch[1])
862	          if (!rec) return sendHtml(res, 404, page('<p>게시물을 찾을 수 없습니다.</p>'))
863	          return sendHtml(res, 200, page(`<h1>게시물 #${escapeHtml(rec.id)}</h1><p>문구: ${escapeHtml(rec.caption)}</p>`))
864	        }
865	        return sendHtml(res, 404, page('<p>not found</p>'))
866	      }).catch((err) => {
867	        try { sendHtml(res, 500, page(`<p>fixture error: ${escapeHtml(err?.message)}</p>`)) } catch { /* ignore */ }
868	      })
869	    },
870	  )
871	  const [port] = await getFreePorts(1)
872	  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', resolve) })
873	  return {
874	    port,
875	    hostResolverRule: `MAP ${REAL_DOMAIN_HOST} 127.0.0.1:${port}`,
876	    async close() { await closeServer(server) },
877	  }
878	}
