331	    const url = (args?.url || getSetting('ai').webhookUrl || '').trim()
332	    if (!/^https?:\/\//i.test(url)) return { ok: false, detail: '웹훅 URL 이 설정되지 않았습니다(설정 > AI).' }
333	    const rows = Array.isArray(args?.rows) ? args.rows.slice(0, 5000) : []
334	    const body = JSON.stringify({ source: 'ezBrowser', count: rows.length, rows, at: Date.now() })
335	    return await new Promise<{ ok: boolean; detail: string }>((resolve) => {
336	      try {
337	        const req = net.request({ url, method: 'POST' })
338	        req.setHeader('content-type', 'application/json')
339	        const timer = setTimeout(() => { try { req.abort() } catch { /* ignore */ }; resolve({ ok: false, detail: '시간 초과' }) }, 20000)
340	        req.on('response', (resp) => {
341	          const status = resp.statusCode ?? 0
342	          resp.on('data', () => { /* drain */ })
343	          resp.on('end', () => { clearTimeout(timer); resolve(status >= 200 && status < 400 ? { ok: true, detail: `전송됨 (${status})` } : { ok: false, detail: `실패 (${status})` }) })
344	          resp.on('error', () => { clearTimeout(timer); resolve({ ok: false, detail: '응답 오류' }) })
345	        })
346	        req.on('error', (err) => { clearTimeout(timer); resolve({ ok: false, detail: err.message }) })
347	        req.write(body); req.end()
348	      } catch (err) { resolve({ ok: false, detail: String(err) }) }
349	    })
350	  })
