1801	  height: number
1802	  alt: string
1803	  area: number
1804	  kind: 'img' | 'canvas'
1805	  frameId?: string       // 자식 프레임 안의 이미지면 그 프레임 키
1806	  frameUrl?: string
1807	}
1808	
1809	const IMAGES_SCRIPT = (cap: number): string => `(() => {
1810	  const out = []; const seen = new Set();
1811	  const push = (src, w, h, alt, kind) => {
1812	    if (!src || seen.has(src)) return;
1813	    // 거대한 data: URI 는 목록에 실으면 IPC 왕복이 폭주한다. 캡처는 캔버스/주소 경로로 따로 한다.
1814	    if (src.slice(0, 5) === 'data:' && src.length > 200000) return;
1815	    seen.add(src);
1816	    const W = Math.round(w) || 0, H = Math.round(h) || 0;
1817	    out.push({ src: String(src).slice(0, 2000), width: W, height: H, alt: String(alt || '').slice(0, 80), area: W * H, kind });
1818	  };
1819	  try {
1820	    for (const im of document.querySelectorAll('img')) {
1821	      if (out.length >= ${cap}) break;
1822	      let r = { width: 0, height: 0 };
1823	      try { r = im.getBoundingClientRect(); } catch (e) {}
1824	      push(im.currentSrc || im.src, im.naturalWidth || r.width, im.naturalHeight || r.height, im.alt, 'img');
1825	    }
1826	    const cvs = document.querySelectorAll('canvas');
1827	    for (let i = 0; i < cvs.length && out.length < ${cap}; i++) {
1828	      const cv = cvs[i];
1829	      push('canvas:' + i, cv.width, cv.height, cv.getAttribute('aria-label') || '', 'canvas');
1830	    }
1831	  } catch (e) {}
1832	  out.sort((a, b) => b.area - a.area);
1833	  return out;
1834	})()`

