        {w.stage === 'failed' && <button className="ai-mini-btn" onClick={onRetry} title="같은 설정으로 다시 시도">↻ 다시 시도</button>}
        {terminal && <button className="ai-history-del" onClick={onDelete} title="목록에서 삭제">×</button>}
