      )}

      {w.stage === 'review' && (
        <>
          <div className="ai-social-preview">
            {previewData === undefined
              ? <span className="ai-hint">미리보기 불러오는 중…</span>
              : previewData
                ? <img src={previewData} alt="생성된 이미지" />
