      id: 'auto-publish', kind: 'harness', modes: ['quick', 'full'],
      script: 'verify-auto-publish.mjs', outArg: false,
      result: (o) => path.join(o, '..', 'auto-publish', 'results.json'),
      timeoutMs: 2 * 60000, desc: '자동 게시 선승인 판정·배선 33종(양성 대조 포함, 공개 API 경로 실행)',
    },
    {
